<?php require __DIR__.'/../includes/app.php';need('System Administrator','Business Manager','Accountant/Cashier');$can=user()['role']!=='Business Manager';$t=$_GET['tab']??'inv';$pdo=db();
function recalc($iid){$i=q('SELECT total_amount,status FROM invoices WHERE invoice_id=?',[$iid])->fetch();if(in_array($i['status'],['void','draft']))return;
 $b=q('SELECT outstanding_balance,total_paid_gross FROM vw_invoice_balances WHERE invoice_id=?',[$iid])->fetch();$s=$b['outstanding_balance']<=0.009?'paid':($b['total_paid_gross']>0?'partially_paid':'issued');q('UPDATE invoices SET status=? WHERE invoice_id=?',[$s,$iid]);}
if($can&&$_SERVER['REQUEST_METHOD']==='POST'){chk();$p=$_POST;$u=user()['id'];
 try{$pdo->beginTransaction();switch($p['act']){
 case 'pay_ok':case 'pay_no':$pm=q('SELECT * FROM payments WHERE payment_id=? AND status="pending" FOR UPDATE',[$p['id']])->fetch();if(!$pm)throw new Exception('Payment not pending.');
  q('UPDATE payments SET status=?,received_by=? WHERE payment_id=?',[$p['act']==='pay_ok'?'completed':'failed',$u,$p['id']]);
  $details=q('SELECT i.customer_id,r.reservation_id,r.reservation_code FROM invoices i LEFT JOIN reservations r USING(reservation_id) WHERE i.invoice_id=?',[$pm['invoice_id']])->fetch();
  $paymentMessage=$p['act']==='pay_ok'?'Your payment of '.money($pm['amount']).' was confirmed by the cashier.':'Your payment of '.money($pm['amount']).' could not be validated. Please contact the cashier for assistance.';
  notify_customer($details['customer_id'],$p['act']==='pay_ok'?'payment_confirmed':'payment_failed','Payment '.($p['act']==='pay_ok'?'confirmed':'needs attention'),$paymentMessage,'payment',$p['id']);
  if($p['act']==='pay_ok')notify_role('Rental Officer','payment_confirmed','Payment confirmed',$details['reservation_code']?'Payment for rental request '.$details['reservation_code'].' has been confirmed.':'A customer payment has been confirmed.','payment',$p['id']);
  if($p['act']==='pay_ok'){recalc($pm['invoice_id']);if($pm['transaction_reference']!==null){$ds=q("SELECT d.deposit_transaction_id FROM deposit_transactions d JOIN invoices i ON i.reservation_id=d.reservation_id WHERE i.invoice_id=? AND d.status='pending' AND d.transaction_type='received' AND d.reference_number=?",[$pm['invoice_id'],$pm['transaction_reference']])->fetchAll(PDO::FETCH_COLUMN);foreach($ds as $d)q("UPDATE deposit_transactions SET status='completed',processed_by=? WHERE deposit_transaction_id=?",[$u,$d]);}}
  else{if($pm['transaction_reference']!==null){$ds=q("SELECT d.deposit_transaction_id FROM deposit_transactions d JOIN invoices i ON i.reservation_id=d.reservation_id WHERE i.invoice_id=? AND d.status='pending' AND d.transaction_type='received' AND d.reference_number=?",[$pm['invoice_id'],$pm['transaction_reference']])->fetchAll(PDO::FETCH_COLUMN);foreach($ds as $d)q("UPDATE deposit_transactions SET status='cancelled',processed_by=? WHERE deposit_transaction_id=?",[$u,$d]);}}
  flash('Payment '.($p['act']==='pay_ok'?'validated.':'rejected.'));break;
 case 'pay_new':$invoiceId=(int)($p['invoice_id']??0);q('SELECT invoice_id FROM invoices WHERE invoice_id=? FOR UPDATE',[$invoiceId])->fetch();$inv=q('SELECT * FROM vw_invoice_balances WHERE invoice_id=?',[$invoiceId])->fetch();if(!$inv||!in_array($inv['status'],['issued','partially_paid','overdue'],true))throw new Exception('This invoice has not been issued or cannot accept payments.');$amount=filter_var($p['amount']??null,FILTER_VALIDATE_FLOAT);if($amount===false||$amount<=0||$amount>$inv['outstanding_balance'])throw new Exception('Amount exceeds the outstanding balance.');if(!in_array($p['method']??'', ['cash','mobile_money','bank_transfer','card'],true))throw new Exception('Select a valid payment method.');
  q("INSERT INTO payments(payment_number,invoice_id,received_by,amount,payment_method,transaction_reference,status) VALUES(?,?,?,?,?,?,'completed')",[code('PAY'),$inv['invoice_id'],$u,$amount,$p['method'],trim($p['ref']??'')?:null]);$paymentId=(int)$pdo->lastInsertId();notify_customer($inv['customer_id'],'payment_confirmed','Payment confirmed','The cashier recorded your payment of '.money($amount).'.','payment',$paymentId);if(!empty($inv['reservation_id']))notify_role('Rental Officer','payment_confirmed','Payment recorded','A customer payment has been recorded for a rental request.','payment',$paymentId);recalc($inv['invoice_id']);flash('Payment recorded.');break;
 case 'create_invoice':$reservationId=(int)($p['reservation_id']??0);$invoice=create_reservation_invoice($reservationId,(int)$u);audit('create_invoice','invoice',$invoice['invoice_id'],'Cashier created or issued invoice for submitted rental application');flash($invoice['created']?'Invoice created and issued. The customer can now submit payment.':'Invoice is already available for this application.');break;
 case 'void':q("UPDATE invoices SET status='void' WHERE invoice_id=? AND status IN('issued','draft')",[$p['id']]);flash('Invoice voided.');break;
 case 'ref_new':$pm=q("SELECT p.amount-COALESCE((SELECT SUM(amount) FROM payment_refunds WHERE payment_id=p.payment_id AND status<>'rejected' AND status<>'failed'),0) a FROM payments p WHERE payment_id=? AND status IN('completed','partially_refunded')",[$p['payment_id']])->fetchColumn();if($pm===false||$p['amount']<=0||$p['amount']>$pm)throw new Exception('Refund exceeds the refundable amount.');
  q("INSERT INTO payment_refunds(payment_id,refund_number,amount,reason,refund_method,status,requested_by) VALUES(?,?,?,?,?,'requested',?)",[$p['payment_id'],code('REF'),$p['amount'],$p['reason'],$p['method'],$u]);flash('Refund requested.');break;
 case 'ref_ok':q("UPDATE payment_refunds SET status='approved',approved_by=? WHERE refund_id=? AND status='requested'",[$u,$p['id']]);flash('Refund approved.');break;
 case 'ref_no':q("UPDATE payment_refunds SET status='rejected' WHERE refund_id=? AND status IN('requested','approved')",[$p['id']]);flash('Refund rejected.');break;
 case 'ref_go':$r=q("SELECT * FROM payment_refunds WHERE refund_id=? AND status='approved' FOR UPDATE",[$p['id']])->fetch();if(!$r)throw new Exception('Refund must be approved first.');
  q("UPDATE payment_refunds SET status='processed',processed_at=NOW(),transaction_reference=? WHERE refund_id=?",[trim($p['ref'])?:null,$p['id']]);
  $pm=q('SELECT amount,invoice_id FROM payments WHERE payment_id=?',[$r['payment_id']])->fetch();$sum=q("SELECT SUM(amount) FROM payment_refunds WHERE payment_id=? AND status='processed'",[$r['payment_id']])->fetchColumn();
  q('UPDATE payments SET status=? WHERE payment_id=?',[$sum>=$pm['amount']?'refunded':'partially_refunded',$r['payment_id']]);recalc($pm['invoice_id']);flash('Refund processed.');break;
 case 'dep_ok':$deposit=q("SELECT reservation_id,customer_id FROM deposit_transactions WHERE deposit_transaction_id=? AND status='pending' FOR UPDATE",[$p['id']])->fetch();if(!$deposit)throw new Exception('Deposit is not pending.');q("UPDATE deposit_transactions SET status='completed',processed_by=? WHERE deposit_transaction_id=? AND status='pending'",[$u,$p['id']]);notify_customer($deposit['customer_id'],'deposit_confirmed','Security deposit confirmed','Your security deposit has been validated by the cashier.','deposit',$deposit['reservation_id']);notify_role('Rental Officer','deposit_confirmed','Security deposit confirmed','A customer security deposit has been validated.','deposit',$deposit['reservation_id']);flash('Deposit validated.');break;
 case 'dep_new':$rt=q('SELECT * FROM rentals WHERE rental_id=?',[$p['rental_id']])->fetch();if(!$rt)throw new Exception('Select a rental.');
  $held=q("SELECT COALESCE(SUM(IF(transaction_type='received',amount,-amount)),0) FROM deposit_transactions WHERE reservation_id=? AND status='completed' AND transaction_type<>'adjustment'",[$rt['reservation_id']])->fetchColumn();
  if($p['type']!=='received'&&$p['amount']>$held)throw new Exception('Amount exceeds the deposit held ('.money($held).').');
  q('INSERT INTO deposit_transactions(reservation_id,rental_id,customer_id,transaction_type,amount,payment_method,reason,processed_by) VALUES(?,?,?,?,?,?,?,?)',[$rt['reservation_id'],$rt['rental_id'],$rt['customer_id'],$p['type'],$p['amount'],$p['method'],$p['reason'],$u]);flash('Deposit transaction saved.');break;}
 audit($p['act'],'finance',$p['id']??$p['invoice_id']??'');$pdo->commit();}catch(Exception $x){if($pdo->inTransaction())$pdo->rollBack();flash($x->getMessage(),'danger');}
 header('Location: finance.php?tab='.$t.(isset($_GET['view'])?'&view='.(int)$_GET['view']:''));exit;}
